/* ============================================================ the phone, and the picker beside it (prototype only) */
const SCREENS = {
  home: Home, sales: SalesList, customers: CustomersList, alerts: Alerts, till: Till, receipt: Receipt, sale: SalePage, customer: Customer, profile: Profile, waiting: Waiting, design: DesignPage,
  payments: PaymentsList, payment: PaymentPage, products: ProductsList, product: ProductPage, movements: Movements, deliveries: Deliveries, delivery: DeliveryPage, receive: Receive,
  suppliers: Suppliers, supplier: SupplierPage, count: Count, expenses: Expenses, accounts: Accounts, account: AccountPage, alertsettings: AlertSettings, users: Users, settings: SettingsPage, receiptsettings: ReceiptSettings,
  phonestatus: PhoneStatus, trailmap: TrailMap, update: UpdatePage, health: BackgroundHealth, sync: SyncPage, conflict: ConflictPage, login: SignIn, twofa: TwoStep, lock: LockView, ended: SessionEnded,
  messages: MessagesList, thread: MessageThread, firstrun: FirstRunDemo,
  spacesearch: SpaceSearch, space: SpaceView, spacesetup: SpaceSetup, choice: ChoiceDemo,
  neworder: NewOrder, othersignin: OtherSignIn, othercode: OtherCode, otherforgot: OtherForgot, otherreset: OtherReset
};
const Screen = { components: { ...SCREENS, Placeholder },
  setup() { const ph = computed(() => S.route.startsWith('ph:') ? S.route.slice(3) : '');
    return { S, ph, SCREENS, pinLeaving }; },
  /* P118 PageTransition: the navigation picks the motion (S.nav: go = push, back = pop, tab = fade); the screen never does.
     The leaving page is pinned where it was (absolute, its own box) so the new one takes its place in the flow; sheets keep the app as their frame. */
  template: `<transition :name="'pg-' + S.nav" @before-leave="pinLeaving"><Placeholder v-if="ph" :key="S.route" :name="ph"/><component :is="S.route" v-else :key="S.route"/></transition>` };

const Picker = { components: { Icon },
  setup() {
    const groups = [
      ['Sell', [['home', 'Home', 'House'], ['waiting', 'Waiting for you', 'Hourglass'], ['till', 'Till', 'ShoppingCart'], ['receipt', 'Sale done, receipt', 'CircleCheck'], ['sales', 'Sales', 'Receipt'], ['sale', 'Sale page', 'FileText'], ['payments', 'Payments', 'Wallet'], ['payment', 'Payment page', 'FileText'], ['neworder', 'New order (lines, P115)', 'ClipboardList']]],
      ['People', [['customers', 'Customers', 'Users'], ['customer', 'Customer page', 'User'], ['suppliers', 'Suppliers', 'Truck'], ['supplier', 'Supplier page', 'User']]],
      ['Stock', [['products', 'Products', 'Package'], ['product', 'Product page', 'FileText'], ['movements', 'Stock movements', 'ArrowLeftRight'], ['deliveries', 'Deliveries', 'PackagePlus'], ['delivery', 'Delivery page', 'FileText'], ['receive', 'Receive stock', 'PackagePlus'], ['count', 'End-of-day count', 'ClipboardCheck']]],
      ['Money', [['expenses', 'Expenses', 'Coins'], ['accounts', 'Accounts', 'Landmark'], ['account', 'Account page', 'FileText']]],
      ['You and the shop', [['alerts', 'Alerts', 'Bell'], ['alertsettings', 'Alerts and reminders', 'BellRing'], ['profile', 'Profile', 'CircleUser'], ['users', 'Users', 'UserCog'], ['settings', 'Settings', 'Settings'], ['receiptsettings', 'Receipt settings', 'ReceiptText'], ['phonestatus', 'This phone', 'Smartphone'], ['trailmap', 'Where this phone was', 'MapPin'], ['update', 'App update', 'CloudDownload'], ['health', 'Background health', 'ShieldCheck'], ['design', 'Design system', 'Palette']]],
      ['Messages (P120)', [['messages', 'Conversations (swipe, Undo)', 'MessageSquare'], ['thread', 'Conversation (bubbles, composer)', 'MessagesSquare'], ['firstrun', 'First run', 'ListChecks']]],
      ['Hidden space (P121)', [['spacesetup', 'Setup (passphrase, recovery key)', 'KeyRound'], ['spacesearch', 'Search (the passphrase opens it)', 'Search'], ['space', 'Hidden (conversations, rules)', 'Lock'], ['choice', 'Block sheet · message details', 'Ban']]],
      ['Getting in', [['login', 'Sign in', 'LogIn'], ['twofa', 'Two-step code', 'ShieldCheck'], ['lock', 'Locked', 'Lock'], ['ended', 'Session ended', 'LockKeyhole']]]
    ];
    const to = (r) => { S.nav = 'tab'; S.done = null; S.stack = []; S.drawer = false; S.sheet = null; S.dialog = null; S.search = false; S.cartOpen = false; if (r === 'till' && !S.cart.length) { addP(PRODUCTS[0]); addP(PRODUCTS[1]); } if (r === 'receipt' && !S.receipt) S.receipt = SALES[0]; S.route = r; };
    const over = {
      drawer: () => { S.sheet = null; S.drawer = true; }, search: () => { S.drawer = false; S.search = true; },
      cart: () => { to('till'); S.cartOpen = true; }, credit: () => { to('till'); S.cartOpen = true; S.customer = 'c1'; S.pay = 'credit'; addP(PRODUCTS[0]); addP(PRODUCTS[0]); S.part = true; S.partAmt = 1000; },
      filter: () => { to('sales'); S.sheet = 'filter'; }, who: () => { to('till'); S.sheet = 'cust'; }, pay: () => { S.route = 'sale'; S.saleId = 'S-1304'; S.sheet = 'takepay'; },
      call: () => { S.route = 'customer'; S.cid = 'c1'; S.sheet = 'call'; }, printer: () => { S.route = 'profile'; S.sheet = 'printer'; },
      reprint: () => { S.stack = ['sales', 'sale']; S.saleId = 'S-1299'; S.recSrc = { kind: 'sale', id: 'S-1299', copy: true }; S.print = 'idle'; S.route = 'receipt'; },
      paymentreceipt: () => { S.stack = ['payments', 'payment']; S.payId = 'P-0089'; S.recSrc = { kind: 'payment', id: 'P-0089', copy: false }; S.print = 'idle'; S.route = 'receipt'; },
      cancelled: () => { S.stack = ['sales', 'sale']; const u = SALES.find(x => x.pay === 'undone') || SALES[5]; S.recSrc = { kind: 'sale', id: u.id, copy: true }; S.print = 'idle'; S.route = 'receipt'; },
      sharesheet: () => { S.route = 'receipt'; S.sheet = 'share'; },
      undo: () => { S.route = 'sale'; S.saleId = 'S-1299'; S.dialog = { title: 'Undo S-1299?', text: 'The stock goes back on the shelf and Neema Kimaro’s balance changes.', action: 'Undo the sale', tone: 'destructive', cancel: 'Keep the sale' }; }
    };
    const states = [['data', 'Data'], ['loading', 'Loading'], ['empty', 'Empty'], ['error', 'Error']];
    /* P102: the data mode, and its states */
    const modes = [['connected', 'Connected'], ['phone', 'On the phone'], ['sync', 'Sync']];
    const setMode = (m) => { SYNCS.mode = m; if (m !== 'sync') SYNCS.running = false; to('home'); };
    const syncState = {
      waiting: () => { SYNCS.mode = 'sync'; to('sync'); },
      conflict: () => { SYNCS.mode = 'sync'; to('home'); S.stack = ['home', 'sync']; S.route = 'conflict'; },
      first: () => { SYNCS.mode = 'sync'; to('home'); firstSync(); },
      signout: () => { SYNCS.mode = 'sync'; if (!SYNCS.waiting.length) SYNCS.waiting.push({ id: 'q9', icon: 'Receipt', what: 'Sale S-1306 · TZS 1,500', when: '11:02' }); to('profile'); signOutAsk(); },
    };
    /* P117: the backend */
    const setBackend = (k) => { BACKEND.kind = k; BACKEND.codeErr = false; to(k === 'other' ? 'othersignin' : 'home'); };
    const backendState = {
      signin: () => { BACKEND.kind = 'other'; to('othersignin'); }, code: () => { BACKEND.kind = 'other'; BACKEND.codeErr = false; codeCountdown(42); to('othercode'); },
      wrong: () => { BACKEND.kind = 'other'; BACKEND.codeErr = true; codeCountdown(0); to('othercode'); }, forgot: () => { BACKEND.kind = 'other'; to('otherforgot'); },
      reset: () => { BACKEND.kind = 'other'; codeCountdown(51); to('otherreset'); }, home: () => { BACKEND.kind = 'other'; to('home'); }
    };
    /* P118: motion, replayed */
    const motion = {
      splash: () => { to('home'); splashPlay(); }, push: () => { to('sales'); setTimeout(() => go('sale', 'S-1304'), 60); }, pop: () => { to('sales'); S.stack = ['sales']; S.route = 'sale'; setTimeout(back, 60); },
      done: () => { to('home'); done({ title: 'Order made', ref: 'SO-0042', text: 'Baraka Mushi pays when the goods are picked up.', facts: [['Customer', 'Baraka Mushi'], ['Lines', '2 lines · 18 units'], ['Total', money(14600)]], primary: ['Print the order', () => toast('Printing SO-0042'), 'Printer'], secondary: ['Make another order', () => { docReset(); go('neworder'); }, 'Plus'] }); },
      printing: () => { to('receipt'); S.receipt = SALES[2]; S.print = 'printing'; },
      steps: () => { docReset(); DOC.c = 'c2'; to('neworder'); setTimeout(() => { DOC.dir = 'step-next'; DOC.step = 1; }, 60); }
    };
    const kbToggle = () => { KB.h = KB.h ? 0 : (innerWidth < 900 ? Math.round(innerHeight * 0.42) : 354); document.body.classList.toggle('keyboard-visible', !!KB.h); };   // P71: stands in for the real keyboard
    return { S, groups, to, over, states, tab, ME, KB, kbToggle, SYNCS, modes, setMode, syncState, BACKEND, setBackend, backendState, motion };
  },
  template: `<div class="space-y-5 text-sm">
    <div><p class="mb-1.5 text-[11px] font-semibold uppercase tracking-wider opacity-60">Signed in as</p><div class="grid grid-cols-2 gap-1 rounded-lg bg-[hsl(var(--canvas))] p-1 ring-1 ring-black/10"><button v-for="r in [['owner','Amina (owner)'],['cashier','Rehema (cashier)']]" :key="r[0]" type="button" @click="S.role = r[0]" :class="['h-8 rounded-md text-xs font-medium', S.role === r[0] ? 'bg-white text-black shadow dark:bg-neutral-700 dark:text-white' : 'opacity-60']">{{ r[1] }}</button></div></div>
    <div><p class="mb-1.5 text-[11px] font-semibold uppercase tracking-wider opacity-60">Theme</p><div class="grid grid-cols-2 gap-1 rounded-lg bg-[hsl(var(--canvas))] p-1 ring-1 ring-black/10"><button type="button" @click="S.dark = false; S.themeMode = 'light'" :class="['h-8 rounded-md text-xs font-medium', !S.dark ? 'bg-white text-black shadow' : 'opacity-60']">Light</button><button type="button" @click="S.dark = true; S.themeMode = 'dark'" :class="['h-8 rounded-md text-xs font-medium', S.dark ? 'bg-neutral-700 text-white shadow' : 'opacity-60']">Dark</button></div></div>
    <div v-for="g in groups" :key="g[0]"><p class="mb-1 text-[11px] font-semibold uppercase tracking-wider opacity-60">{{ g[0] }}</p><div class="grid gap-0.5"><button v-for="s in g[1]" :key="s[0]" type="button" @click="to(s[0])" :class="['flex h-8 items-center gap-2 rounded-md px-2 text-left', S.route === s[0] ? 'bg-black/10 font-medium dark:bg-white/15' : 'hover:bg-black/5 dark:hover:bg-white/10']"><Icon :name="s[2]" :size="14" class="opacity-60"/>{{ s[1] }}</button></div></div>
    <div><p class="mb-1.5 text-[11px] font-semibold uppercase tracking-wider opacity-60">Data mode (P102)</p><div class="grid grid-cols-3 gap-1 rounded-lg bg-[hsl(var(--canvas))] p-1 ring-1 ring-black/10"><button v-for="m in modes" :key="m[0]" type="button" @click="setMode(m[0])" :data-mode="m[0]" :class="['h-8 rounded-md text-[11px] font-medium', SYNCS.mode === m[0] ? 'bg-white shadow-sm dark:bg-neutral-700' : 'opacity-70']">{{ m[1] }}</button></div>
      <div class="mt-1 grid grid-cols-2 gap-1"><button v-for="o in [['waiting', 'Changes waiting'], ['conflict', 'A conflict'], ['first', 'First sync'], ['signout', 'Sign out, changes waiting']]" :key="o[0]" type="button" @click="syncState[o[0]]()" :data-sync-state="o[0]" class="h-8 rounded-md px-2 text-left text-xs hover:bg-black/5 dark:hover:bg-white/10">{{ o[1] }}</button></div></div>
    <div><p class="mb-1.5 text-[11px] font-semibold uppercase tracking-wider opacity-60">Backend (P117)</p><div class="grid grid-cols-2 gap-1 rounded-lg bg-[hsl(var(--canvas))] p-1 ring-1 ring-black/10"><button v-for="b in [['kit', 'The kit’s API'], ['other', 'Another backend']]" :key="b[0]" type="button" @click="setBackend(b[0])" :data-backend="b[0]" :class="['h-8 rounded-md text-[11px] font-medium', BACKEND.kind === b[0] ? 'bg-white shadow-sm dark:bg-neutral-700' : 'opacity-70']">{{ b[1] }}</button></div>
      <div class="mt-1 grid grid-cols-2 gap-1"><button v-for="o in [['signin', 'Sign in'], ['code', 'Code by SMS'], ['wrong', 'Wrong code'], ['forgot', 'Forgot password'], ['reset', 'Reset with the code'], ['home', 'Home: one organisation, no alerts']]" :key="o[0]" type="button" @click="backendState[o[0]]()" class="h-8 rounded-md px-2 text-left text-xs hover:bg-black/5 dark:hover:bg-white/10">{{ o[1] }}</button></div></div>
    <div><p class="mb-1.5 text-[11px] font-semibold uppercase tracking-wider opacity-60">Motion (P118)</p><div class="grid grid-cols-2 gap-1"><button v-for="o in [['splash', 'Splash opens'], ['push', 'Open a record (push)'], ['pop', 'Back (pop)'], ['steps', 'Wizard step'], ['done', 'Done moment'], ['printing', 'Printing']]" :key="o[0]" type="button" @click="motion[o[0]]()" class="h-8 rounded-md px-2 text-left text-xs hover:bg-black/5 dark:hover:bg-white/10">{{ o[1] }}</button>
      <button type="button" @click="S.reduce = !S.reduce" :class="['h-8 rounded-md px-2 text-left text-xs', S.reduce ? 'bg-black/10 font-medium dark:bg-white/15' : 'hover:bg-black/5 dark:hover:bg-white/10']">Reduce motion</button><button type="button" @click="S.slowmo = !S.slowmo" :class="['h-8 rounded-md px-2 text-left text-xs', S.slowmo ? 'bg-black/10 font-medium dark:bg-white/15' : 'hover:bg-black/5 dark:hover:bg-white/10']">Slow motion</button></div></div>
    <div><p class="mb-1.5 text-[11px] font-semibold uppercase tracking-wider opacity-60">Phone state</p><div class="grid grid-cols-2 gap-1"><button type="button" @click="S.net = S.net === 'offline' ? 'online' : 'offline'" :class="['h-8 rounded-md px-2 text-left text-xs', S.net === 'offline' ? 'bg-black/10 font-medium dark:bg-white/15' : 'hover:bg-black/5 dark:hover:bg-white/10']">No signal</button><button type="button" @click="S.update = S.update === 'available' ? null : 'available'" :class="['h-8 rounded-md px-2 text-left text-xs', S.update === 'available' ? 'bg-black/10 font-medium dark:bg-white/15' : 'hover:bg-black/5 dark:hover:bg-white/10']">Update ready</button><button type="button" @click="S.update = S.update === 'required' ? null : 'required'" :class="['h-8 rounded-md px-2 text-left text-xs', S.update === 'required' ? 'bg-black/10 font-medium dark:bg-white/15' : 'hover:bg-black/5 dark:hover:bg-white/10']">Update required</button><button type="button" @click="S.printFail = S.printFail === 'off' ? null : 'off'" :class="['h-8 rounded-md px-2 text-left text-xs', S.printFail === 'off' ? 'bg-black/10 font-medium dark:bg-white/15' : 'hover:bg-black/5 dark:hover:bg-white/10']">Printer is off</button><button type="button" @click="S.printFail = S.printFail === 'bt' ? null : 'bt'" :class="['h-8 rounded-md px-2 text-left text-xs', S.printFail === 'bt' ? 'bg-black/10 font-medium dark:bg-white/15' : 'hover:bg-black/5 dark:hover:bg-white/10']">Bluetooth is off</button><button type="button" @click="S.printFail = S.printFail === 'none' ? null : 'none'" :class="['h-8 rounded-md px-2 text-left text-xs', S.printFail === 'none' ? 'bg-black/10 font-medium dark:bg-white/15' : 'hover:bg-black/5 dark:hover:bg-white/10']">No printer chosen</button><button type="button" @click="S.map = S.map === 'none' ? 'path' : 'none'; S.route = 'trailmap'" :class="['h-8 rounded-md px-2 text-left text-xs', S.map === 'none' ? 'bg-black/10 font-medium dark:bg-white/15' : 'hover:bg-black/5 dark:hover:bg-white/10']">Map: no trail</button><button type="button" @click="S.map = S.map === 'tiles' ? 'path' : 'tiles'; S.route = 'trailmap'" :class="['h-8 rounded-md px-2 text-left text-xs', S.map === 'tiles' ? 'bg-black/10 font-medium dark:bg-white/15' : 'hover:bg-black/5 dark:hover:bg-white/10']">Map: no network</button><button type="button" @click="S.phoneNet = S.phoneNet === 'mobile' ? 'wifi' : 'mobile'; S.route = 'phonestatus'" :class="['h-8 rounded-md px-2 text-left text-xs', S.phoneNet === 'mobile' ? 'bg-black/10 font-medium dark:bg-white/15' : 'hover:bg-black/5 dark:hover:bg-white/10']">Phone: mobile data</button><button type="button" @click="S.phoneNet = S.phoneNet === 'none' ? 'wifi' : 'none'; S.route = 'phonestatus'" :class="['h-8 rounded-md px-2 text-left text-xs', S.phoneNet === 'none' ? 'bg-black/10 font-medium dark:bg-white/15' : 'hover:bg-black/5 dark:hover:bg-white/10']">Phone: no signal</button><button type="button" @click="kbToggle" :class="['h-8 rounded-md px-2 text-left text-xs', KB.h ? 'bg-black/10 font-medium dark:bg-white/15' : 'hover:bg-black/5 dark:hover:bg-white/10']">Keyboard open</button></div></div>
    <div><p class="mb-1.5 text-[11px] font-semibold uppercase tracking-wider opacity-60">Open on top</p><div class="grid grid-cols-2 gap-1"><button v-for="o in [['drawer','Drawer'],['search','Search'],['cart','Cart'],['credit','Credit, part paid'],['filter','Filters'],['who','Who is buying'],['pay','Take payment'],['call','Call sheet'],['printer','Printer'],['reprint','Reprint a sale'],['paymentreceipt','Payment receipt'],['cancelled','Cancelled sale receipt'],['sharesheet','Share list'],['undo','Confirm undo']]" :key="o[0]" type="button" @click="over[o[0]]()" class="h-9 rounded-md px-2 text-left text-xs hover:bg-black/5 dark:hover:bg-white/10">{{ o[1] }}</button></div></div>
    <div><p class="mb-1.5 text-[11px] font-semibold uppercase tracking-wider opacity-60">List state</p><div class="grid grid-cols-4 gap-1 rounded-lg bg-[hsl(var(--canvas))] p-1 ring-1 ring-black/10"><button v-for="s in states" :key="s[0]" type="button" @click="S.list = s[0]; if (S.route !== 'sales') to('sales')" :class="['h-8 rounded-md text-[11px] font-medium', S.list === s[0] ? 'bg-white text-black shadow dark:bg-neutral-700 dark:text-white' : 'opacity-60']">{{ s[1] }}</button></div></div></div>` };

const Root = { components: { Screen, TabBar, Drawer, SearchView, PhoneSheets, Confirm, Toast, Picker, Icon, NetBar, UpdateOffer, UpdateRequired, FirstSync, SplashOpen, DoneMoment },
  setup() {
    const scale = ref(1), narrow = ref(false), menu = ref(false);
    const fit = () => { narrow.value = innerWidth < 900; scale.value = narrow.value ? 1 : Math.min(1, (innerHeight - 32) / 844); };
    onMounted(() => { fit(); addEventListener('resize', fit); });
    onBeforeUnmount(() => removeEventListener('resize', fit));
    const clock = new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
    watch(() => S.dark, (d) => document.documentElement.setAttribute('data-theme', d ? 'dark' : 'light'), { immediate: true });
    const bar = computed(() => TABS.includes(S.route));
    return { S, scale, narrow, menu, clock, bar, KB };
  },
  template: `<div :class="narrow ? '' : 'flex min-h-screen items-center justify-center gap-10 p-4'" :style="narrow ? 'height:100dvh' : ''">
    <aside v-if="!narrow" class="w-64 shrink-0 rounded-xl bg-[hsl(var(--canvas))] p-4 text-[hsl(240_10%_20%)] ring-1 ring-black/10 dark:text-neutral-200 dark:ring-white/10"><h1 class="mb-1 text-base font-semibold">Bootbox Phone</h1><p class="mb-5 text-xs opacity-70">The shop drawn for a phone only. Everything is clickable. This panel is not part of the app.</p><Picker/></aside>
    <div :style="narrow ? '' : { width: (390 * scale) + 'px', height: (844 * scale) + 'px' }" :class="narrow ? 'h-full w-full' : 'shrink-0'"><div :class="narrow ? 'h-full w-full' : 'origin-top-left'" :style="narrow ? '' : { transform: 'scale(' + scale + ')', width: '390px', height: '844px' }">
      <div :class="['app relative flex flex-col overflow-hidden', S.dark ? 'dark' : '', S.reduce ? 'reduce' : '', S.slowmo ? 'slowmo' : '', S.net === 'offline' ? 'topbar' : '', narrow ? 'h-full w-full' : 'h-[844px] w-[390px] rounded-[44px] border-[10px] border-[#18181b] shadow-2xl ring-1 ring-black/10']" :style="KB.h ? { paddingBottom: KB.h + 'px' } : null">
        <div v-if="!narrow" class="pointer-events-none absolute inset-x-0 top-0 z-[100] flex h-[30px] items-center justify-between px-7 text-xs font-semibold"><span>{{ clock }}</span><span class="absolute left-1/2 top-1.5 h-5 w-20 -translate-x-1/2 rounded-full bg-[#18181b]"></span><span class="flex items-center gap-1"><Icon name="Signal" :size="12"/><Icon name="Wifi" :size="12"/><Icon name="BatteryFull" :size="14"/></span></div>
        <NetBar/><Screen/><TabBar v-if="bar"/><Drawer/><SearchView/><PhoneSheets/><Confirm/><UpdateOffer/><Toast/><DoneMoment/><UpdateRequired/><FirstSync/><SplashOpen/>
        <div v-if="KB.h" class="absolute inset-x-0 bottom-0 z-[110] grid place-items-center bg-neutral-300 text-center text-xs text-neutral-600 dark:bg-neutral-700 dark:text-neutral-300" :style="{ height: KB.h + 'px' }" aria-label="On-screen keyboard (stand-in)"><span class="px-6">On-screen keyboard (stand-in). On Android 10 the page is not resized: it lies on top of the screen.</span></div></div></div></div>
    <template v-if="narrow"><button v-if="!S.sheet && !S.drawer && !S.dialog" type="button" class="fixed left-3 z-[200] flex items-center gap-2 rounded-full border bg-white px-3 py-2 text-xs font-medium text-black shadow-lg" style="bottom: calc(86px + env(safe-area-inset-bottom, 0px))" @click="menu = !menu"><Icon name="Map" :size="14"/>States</button>
      <div v-if="menu" class="fixed inset-x-3 bottom-32 z-[200] max-h-[70dvh] overflow-y-auto rounded-xl bg-white p-4 text-black shadow-2xl"><Picker/></div></template></div>`
};
createApp(Root).mount('#root');
